def _gjson_path(expr: str, data: str) -> str:
    if not data:
        return ""
    parsed = json.loads(data)  # raises on invalid JSON
    parts = expr.split(".")
    node = parsed
    i = 0
    while i < len(parts):
        part = parts[i]
        if part == "#":
            # count
            if isinstance(node, list):
                return str(len(node))
            return ""
        if i + 1 < len(parts) and part == "#":
            pass  # handled above
        # array wildcard: current part is "#" already handled; check next is a field
        if part == "#" and i + 1 < len(parts):
            field = parts[i + 1]
            if isinstance(node, list):
                return "\n".join(str(item.get(field, "")) if isinstance(item, dict) else "" for item in node)
            return ""
        if isinstance(node, list):
            if part.isdigit():
                idx = int(part)
                if idx >= len(node):
                    return ""
                node = node[idx]
            else:
                return ""
        elif isinstance(node, dict):
            node = node.get(part)
            if node is None:
                return ""
        else:
            return ""
        i += 1
    if isinstance(node, (dict, list)):
        return json.dumps(node)
    return str(node) if node is not None else ""


